    // Clean Spot Screen
    cleanSpotGuide: 'Clean Spot Guide',
    checkTheArea: 'Check the Area',
    checkTheAreaContent: 'Inspect the prayer area thoroughly. Look for any visible impurities, dirt, or najis (ritual impurities). The area should be free from urine, blood, alcohol, or other impure substances. Ensures your prayer is performed in ritual purity.',
    removeImpurities: 'Remove Impurities',
    removeImpuritiesContent: 'Clean any impurities if found. If you find any impurities, clean them with water. For solid impurities, remove them physically. For liquid impurities, wash with clean water until removed. Purifies the space for valid prayer.',
    chooseAppropriateSurface: 'Choose Appropriate Surface',
    chooseAppropriateSurfaceContent: 'Select a suitable surface for prayer. Choose a flat, stable surface. Natural earth, clean floor tiles, or prayer mats are ideal. Avoid praying on beds, soft cushions, or uneven surfaces. Provides stability and focus during prayer.',
    placePrayerMat: 'Place Prayer Mat',
    placePrayerMatContent: 'Layout your prayer mat properly. Unfold your prayer mat completely, ensuring it\'s straight and facing the Qibla. The mat should be clean and dry. If no mat is available, ensure the floor is clean. Creates a defined sacred space for prayer.',
    removeFootwear: 'Remove Footwear',
    removeFootwearContent: 'Take off shoes and socks if needed. Remove your shoes and place them away from the prayer area. If wearing socks, ensure they are clean. Some scholars prefer bare feet for better connection with the earth. Shows respect and maintains cleanliness.',
    finalInspection: 'Final Inspection',
    finalInspectionContent: 'Do a final check of your prayer space. Take a moment to ensure everything is in order. Check that your space is clean, facing the right direction, and free from distractions. Ensures complete readiness for prayer.',
