    dressingGuide: 'Dressing Guide',
    understandAwrah: 'Understand Awrah',
    understandAwrahContent: 'Learn what parts must be covered. Awrah refers to the parts of the body that must be covered during prayer. For men, this is from the navel to the knees. For women, the entire body except face and hands (according to majority of scholars). Ensures proper modesty before Allah.',
    chooseCleanClothes: 'Choose Clean Clothes',
    chooseCleanClothesContent: 'Select clean and pure garments. Ensure your clothes are physically clean and free from najis (ritual impurities) like blood, urine, or alcohol. If uncertain, wash the garment or choose another one. Physical and spiritual purity for prayer.',
    properCoverage: 'Proper Coverage',
    properCoverageContent: 'Ensure adequate coverage of awrah. Men: Cover from navel to knees with opaque clothing. Women: Cover entire body with loose, opaque clothing, leaving face and hands visible. Avoid transparent or tight-fitting clothes. Maintains Islamic modesty standards.',
    removeDistractingItems: 'Remove Distracting Items',
    removeDistractingItemsContent: 'Remove jewelry and distracting accessories. Remove excessive jewelry, watches with alarms, or anything that might distract you during prayer. Simple wedding rings are generally acceptable. Turn off or silence electronic devices. Enhances focus and concentration.',
    checkForSilk: 'Check for Silk (Men)',
    checkForSilkContent: 'Men should avoid pure silk garments. Islamic law generally prohibits men from wearing pure silk during prayer (and in general). Mixed fabrics with small amounts of silk are usually acceptable. Women may wear silk without restriction. Follows Islamic clothing guidelines.',
    headCovering: 'Head Covering (Women)',
    headCoveringContent: 'Women should cover their hair. Women should wear a hijab, scarf, or head covering that conceals the hair and neck. The covering should be opaque and not see-through. Ensure it stays secure during prayer movements. Completes the modesty requirements.',
    comfortableFit: 'Comfortable Fit',
    comfortableFitContent: 'Ensure clothing allows proper movement. Your clothing should be loose enough to allow for prostration (sujud), bowing (ruku), and standing movements. Tight clothing that restricts movement or reveals body shape should be avoided. Enables proper prayer positions.',
    finalCheck: 'Final Check',
    finalCheckContent: 'Review your dress before prayer. Do a final check in a mirror if available. Ensure all requirements are met: awrah covered, clothes clean, no distracting items, and you feel comfortable and modest. Confidence and readiness for prayer.',
