    namesOfAllah: '99 Names of Allah',
    
    // 99 Names of Allah Screen
    namesOfAllahTitle: 'The 99 Beautiful Names of Allah',
    namesOfAllahIntro: 'The 99 Beautiful Names of Allah (Asma ul-Husna) are the perfect names and attributes that describe Allah\'s nature and qualities. Reciting and reflecting upon these names brings us closer to understanding Allah\'s magnificence and mercy.',
    audioPronunciation: 'Audio Pronunciation',
    playingPronunciation: 'Playing pronunciation of',
    audioError: 'Unable to play audio at this time.',
    pronouncedAs: 'Pronounced as',
    meaning: 'Meaning',
    
    // Ghusl Screen
    ghuslGuide: 'Ghusl Guide',
    ghuslIntentionNiyyah: 'Intention (Niyyah)',
    ghuslIntentionContent: 'Make the intention in your heart to perform ghusl for purification. Formulate the intention (niyyah) for ghusl in your heart. You do not need to say it aloud. Focus on purifying yourself for Allah.',
    sayBismillah: 'Say Bismillah',
    sayBismillahContent: 'Begin by saying "Bismillah" (In the name of Allah). Say "Bismillah" before starting. This is recommended for all acts of worship.',
    washPrivateParts: 'Wash Private Parts',
    washPrivatePartsContent: 'Wash any impurity from the private parts thoroughly. Remove any physical impurity (najasa) from the private parts. Use your left hand and clean thoroughly. Wash your hand after cleaning.',
    performWudu: 'Perform Wudu',
    performWuduContent: 'Perform a complete wudu (ablution) as for prayer. Perform wudu as you would for prayer. Delay washing the feet until the end if standing on the ground.',
    pourWaterOverHead: 'Pour Water Over Head',
    pourWaterOverHeadContent: 'Pour water over your head three times, ensuring it reaches the roots of the hair. Pour water over the head three times. Ensure water reaches the scalp and roots of the hair. Rub the hair with fingers if needed.',
    washEntireBody: 'Wash Entire Body',
    washEntireBodyContent: 'Wash the entire body, starting with the right side, then the left, ensuring no part is left dry. Wash the right side of the body, then the left. Ensure water reaches all skin, including armpits, inside the navel, and between toes. Rub the body with your hands to ensure complete coverage.',
    washFeetIfDelayed: 'Wash Feet (if delayed)',
    washFeetIfDelayedContent: 'If you delayed washing your feet during wudu, wash them now. Wash both feet up to and including the ankles. Clean between the toes. Repeat three times for each foot.',
    ghuslComplete: 'Ghusl Complete',
    ghuslCompleteContent: 'You have completed ghusl and are now in a state of major purity. You may now pray, recite Quran, or perform other acts of worship. Maintain your state of purity.',
    
    // Umrah Screen
    umrahGuide: 'Umrah Guide',
    whatIsUmrah: 'What is Umrah?',
    whatIsUmrahContent: 'Umrah is a voluntary pilgrimage to Mecca that can be performed at any time of the year. Unlike Hajj, it is not mandatory but is highly recommended and brings great spiritual rewards.',
    whenToPerformUmrah: 'When to Perform Umrah?',
    whenToPerformUmrahContent: 'Umrah can be performed at any time of the year, except during the days of Hajj (8th-13th of Dhul Hijjah). Many Muslims prefer to perform it during Ramadan for greater rewards.',
    ihramForUmrah: 'Ihram for Umrah',
    ihramForUmrahContent: 'Enter the sacred state of Ihram at designated Miqat points. Wear two white unstitched cloths (for men) or modest clothing (for women). Make intention for Umrah and recite Talbiyah.',
    tawaf: 'Tawaf',
    tawafContent: 'Perform Tawaf around the Kaaba seven times, starting from the Black Stone. Each circuit begins and ends at the Black Stone. Recite: \'Bismillah, Allahu Akbar\' when touching the Black Stone.',
    sai: 'Sa\'i',
    saiContent: 'Walk seven times between Safa and Marwah hills. Start from Safa, walk to Marwah, then return to Safa (one complete round). Recite: \'Inna Safa wal Marwata min sha\'a\'irillah\' when starting.',
    halqOrTaqsir: 'Halq or Taqsir',
    halqOrTaqsirContent: 'Cut the hair to complete Umrah. Men can either shave their head completely (Halq) or trim their hair (Taqsir). Women only trim a small portion. Recite: \'Allahumma inni as\'aluka ridaka wal jannah\'.',
    duasAndSupplications: 'Duas and Supplications',
    duasAndSupplicationsContent: 'Throughout Umrah, recite various supplications and prayers. Learn the specific duas for each ritual to enhance the spiritual experience and connection with Allah.',
    virtuesOfUmrah: 'Virtues of Umrah',
    virtuesOfUmrahContent: 'Umrah expiates sins and brings great rewards. The Prophet (ﷺ) said that performing Umrah during Ramadan is equivalent to performing Hajj with him.',
    preparation: 'Preparation',
    preparationContent: 'Before Umrah, ensure you have proper documentation, vaccinations, and understand the rituals. Learn the Arabic phrases and duas for a more meaningful experience.',
    completion: 'Completion',
    completionContent: 'After completing all rituals, you exit the state of Ihram and can resume normal activities. The spiritual benefits and closeness to Allah remain with you.',
    
    // Hajj Screen
    hajjGuide: 'Hajj Guide',
    whatIsHajj: 'What is Hajj?',
    whatIsHajjContent: 'Hajj is the annual Islamic pilgrimage to Mecca, Saudi Arabia. It is one of the five pillars of Islam and is mandatory for every Muslim who is physically and financially able to perform it at least once in their lifetime.',
    whenIsHajj: 'When is Hajj?',
    whenIsHajjContent: 'Hajj takes place during the Islamic month of Dhul Hijjah, specifically from the 8th to the 12th day. The exact dates vary each year as they follow the lunar calendar.',
    ihram: 'Ihram',
    ihramContent: 'Enter the sacred state of Ihram. Wear two white unstitched cloths (for men) or modest clothing (for women). Make intention for Hajj and recite Talbiyah.',
    tawafAlQudum: 'Tawaf al-Qudum',
    tawafAlQudumContent: 'Perform the arrival Tawaf around the Kaaba seven times, starting from the Black Stone. Each circuit begins and ends at the Black Stone.',
    arafat: 'Arafat',
    arafatContent: 'Stand at Arafat from noon until sunset on the 9th of Dhul Hijjah. This is the most important day of Hajj. Spend time in prayer, dua, and seeking forgiveness.',
    muzdalifah: 'Muzdalifah',
    muzdalifahContent: 'After sunset, travel to Muzdalifah and spend the night there. Collect 49 pebbles (21 for the first day of stoning, 7 for each of the next three days). Pray Maghrib and Isha combined.',
    stoningTheDevil: 'Stoning the Devil',
    stoningTheDevilContent: 'Throw pebbles at the three pillars (Jamarat) representing the devil. Throw 7 pebbles at each pillar, saying \'Allahu Akbar\' with each throw.',
    sacrifice: 'Sacrifice',
    sacrificeContent: 'Sacrifice an animal (sheep, goat, or cow) on Eid al-Adha. After sacrifice, eat some meat and distribute the rest.',
    finalTawaf: 'Final Tawaf',
    finalTawafContent: 'Perform the farewell Tawaf before leaving Mecca. This marks the completion of Hajj.',
    
    // Common terms for Umrah and Hajj
