    aboutMeIntroduction: 'My name is Moustapha, and I am the creator of Hudā. I am 18 years old at the time of release, and I have been Muslim my entire life, alhamdulillāh. Although I was born into Islam, I understand that many people come to Islam later in life, and I have immense respect for those who find their way to the truth.',
