    aboutTheDeveloper: 'Acerca del Desarrollador',
    clickToLearnMoreAboutDeveloper: 'Haz clic para conocer más sobre el Desarrollador de Hudā',
    aboutMeGreeting: 'As-salāmu ʿalaykum wa raḥmatullāh,',
    aboutMeIntroduction: 'Mi nombre es Moustapha, y soy el creador de Hudā. Tengo 18 años al momento del lanzamiento, y he sido musulmán toda mi vida, alhamdulillāh. Aunque nací en el Islam, entiendo que el viaje de fe es profundamente personal. Cada uno tiene su propio camino, sus propias preguntas y sus propias luchas. Por eso construí Hudā — para ayudar a aquellos que son nuevos en el Islam o que apenas están comenzando a explorarlo.',
    aboutMeDevelopment: 'Esta aplicación fue desarrollada completamente por mí. Cada parte de ella — el diseño, el código, el contenido — fue creada con cuidado, intención y la esperanza de que pudiera hacer una diferencia. Quería proporcionar algo claro, accesible y reconfortante para cualquiera que busque entender mejor el Islam.',
    aboutMeHeart: 'Hudā no es solo una aplicación; es un proyecto del corazón. Es mi forma de devolver y usar las habilidades que Allah me ha bendecido para beneficiar a otros, in shā\' Allāh. Todavía estoy aprendiendo y creciendo cada día, y espero seguir mejorando Hudā y agregando más funciones con el tiempo.',
    aboutMePrayer: 'Que Allah nos guíe a todos, nos aumente en conocimiento y haga de este esfuerzo una fuente de recompensa.',
    aboutMeThankYou: 'Gracias por estar aquí. Realmente te deseo lo mejor en tu viaje.',
    aboutMeClosing: 'Was-salāmu ʿalaykum wa raḥmatullāhi wa barakātuh.',
