    // Settings Screen Additional
    name: 'Nom',
    email: 'Email',
    notProvided: 'Non fourni',
    accountCreated: 'Compte Créé',
    unknown: 'Inconnu',
    prayerTimeDifferences: 'Différences d\'Heures de Prière',
    aboutTheDeveloper: 'À Propos du Développeur',
    clickToLearnMoreAboutDeveloper: 'Cliquez pour en savoir plus sur le Développeur de Hudā',
    aboutMeGreeting: 'As-salāmu ʿalaykum wa raḥmatullāh,',
    aboutMeIntroduction: 'Je m\'appelle Moustapha, et je suis le créateur de Hudā. J\'ai 18 ans au moment de la sortie, et j\'ai été musulman toute ma vie, alhamdulillāh. Même si je suis né dans l\'Islam, je comprends que le voyage de la foi est profondément personnel. Chacun a son propre chemin, ses propres questions et ses propres luttes. C\'est pourquoi j\'ai construit Hudā — pour aider ceux qui sont nouveaux dans l\'Islam ou qui commencent tout juste à l\'explorer.',
    aboutMeDevelopment: 'Cette application a été entièrement développée par moi. Chaque partie — le design, le code, le contenu — a été créée avec soin, intention et l\'espoir qu\'elle pourrait faire une différence. Je voulais fournir quelque chose de clair, accessible et réconfortant pour quiconque cherche à mieux comprendre l\'Islam.',
    aboutMeHeart: 'Hudā n\'est pas seulement une application ; c\'est un projet du cœur. C\'est ma façon de redonner et d\'utiliser les compétences qu\'Allah m\'a bénies pour bénéficier aux autres, in shā\' Allāh. J\'apprends et je grandis encore chaque jour, et j\'espère continuer à améliorer Hudā et ajouter plus de fonctionnalités au fil du temps.',
