    // Prayer content translations
    iqamaText: 'Allah è il Più Grande, Allah è il Più Grande. Testimonio che non c\'è dio se non Allah. Testimonio che Muhammad è il Messaggero di Allah. Venite alla preghiera. Venite al successo. La preghiera è iniziata, la preghiera è iniziata. Allah è il Più Grande, Allah è il Più Grande. Non c\'è dio se non Allah.',
    takbirText: 'Allah è il Più Grande',
    fatihaText: 'Nel nome di Allah, il Compassionevole, il Misericordioso. Lode ad Allah, Signore dei mondi. Il Compassionevole, il Misericordioso. Padrone del Giorno del Giudizio. Solo Te adoriamo e solo da Te imploriamo aiuto. Guidaci sulla retta via, la via di coloro che hai colmato di favori, non di coloro che hanno meritato la Tua ira, né degli sviati.',
