    aboutMeIntroduction: 'Mi chiamo Moustapha e sono il creatore di Hudā. Ho 18 anni al momento del rilascio e sono musulmano da tutta la vita, alhamdulillāh. Anche se sono nato nell\'Islam, capisco che il percorso della fede è profondamente personale. Ognuno ha il proprio cammino, le proprie domande e le proprie difficoltà. Ecco perché ho creato Hudā — per aiutare coloro che sono nuovi all\'Islam o che stanno appena iniziando a esplorarlo.',
