// Function to get translation
export const t = (key, language = 'english') => {
  const lang = translations[language] || translations.english;
  return lang[key] || key;
};

// Function to get current language from AsyncStorage
export const getCurrentLanguage = async () => {
  try {
    const language = await AsyncStorage.getItem('userLanguage');
    return language || 'english';
  } catch (error) {
    console.error('Error getting language:', error);
    return 'english';
  }
};

// Function to set current language
export const setCurrentLanguage = async (language) => {
  try {
    await AsyncStorage.setItem('userLanguage', language);
    
    // Also save to Firebase if user is logged in
    try {
      const { auth, firestore } = await import('../firebase');
      const { doc, updateDoc, serverTimestamp } = await import('firebase/firestore');
      
      const user = auth.currentUser;
      if (user) {
        await updateDoc(doc(firestore, 'users', user.uid), {
          language: language,
          updatedAt: serverTimestamp()
        });
        console.log('✅ Language saved to Firebase:', language);
      }
    } catch (firebaseError) {
      console.log('⚠️ Could not save language to Firebase (user may not be logged in):', firebaseError.message);
    }
  } catch (error) {
    console.error('Error setting language:', error);
  }
};

// Function to get notification title with formatting
export const getNotificationTitle = (key, language = 'english', replacements = {}) => {
  const title = t(key, language);
  
  // Replace placeholders with actual values
  let formattedTitle = title;
  Object.keys(replacements).forEach(key => {
    formattedTitle = formattedTitle.replace(`{${key}}`, replacements[key]);
  });
  
  return formattedTitle;
}; 